  static CricketPlayer? getPlayerById(String id) {
    try {
      return allPlayers.firstWhere((p) => p.id == id);
    } catch (_) {
      return null;
    }
  }

  static List<CricketPlayer> getBatters() {
    return allPlayers.where((p) => p.role == 'Batter' || p.role == 'Wicket-Keeper' || p.role == 'All-Rounder').toList();
  }

  static List<CricketPlayer> getBowlers() {
    return allPlayers.where((p) => p.role == 'Bowler' || p.role == 'All-Rounder').toList();
  }

  static List<CricketPlayer> getPureBatters() {
    return allPlayers.where((p) => p.role == 'Batter').toList();
  }

  static List<CricketPlayer> getPureBowlers() {
    return allPlayers.where((p) => p.role == 'Bowler').toList();
  }

  static List<CricketPlayer> getWicketKeepers() {
    return allPlayers.where((p) => p.role == 'Wicket-Keeper').toList();
  }

  static List<CricketPlayer> getAllRounders() {
    return allPlayers.where((p) => p.role == 'All-Rounder').toList();
  }
}
